{"implementation":"def solve(case):
    def require_int(value, field):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(field + ' must be an integer')
        return value

    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    if 'segments' not in case or 'budget' not in case:
        raise ValueError('case requires segments and budget')
    segments = case['segments']
    if not isinstance(segments, list):
        raise ValueError('segments must be an array')
    budget = require_int(case['budget'], 'budget')

    allocations = []
    names = []
    importances = []
    capacities = []
    seen_names = set()
    minimum_total = 0
    capacity_total = 0

    for index, segment in enumerate(segments):
        if not isinstance(segment, dict):
            raise ValueError('each segment must be an object')
        for field in ('name', 'importance', 'minimum', 'capacity'):
            if field not in segment:
                raise ValueError('segment missing ' + field)
        name = segment['name']
        if not isinstance(name, str):
            raise ValueError('name must be a string')
        if name in seen_names:
            raise ValueError('segment names must be unique')
        seen_names.add(name)
        importance = require_int(segment['importance'], 'importance')
        minimum = require_int(segment['minimum'], 'minimum')
        capacity = require_int(segment['capacity'], 'capacity')
        if importance < 0:
            raise ValueError('importance must be nonnegative')
        if minimum < 0 or capacity < minimum:
            raise ValueError('invalid minimum or capacity')
        names.append(name)
        importances.append(importance)
        allocations.append(minimum)
        capacities.append(capacity)
        minimum_total += minimum
        capacity_total += capacity

    if budget < minimum_total or budget > capacity_total:
        raise ValueError('budget is outside feasible bounds')

    remaining = budget - minimum_total
    while remaining:
        best = None
        for index in range(len(allocations)):
            if allocations[index] >= capacities[index]:
                continue
            if best is None:
                best = index
                continue
            # Compare importance/(next allocated position) exactly.
            if importances[index] * (allocations[best] + 1) > importances[best] * (allocations[index] + 1):
                best = index
        allocations[best] += 1
        remaining -= 1

    return {
        'allocations': allocations,
        'by_name': {name: allocations[index] for index, name in enumerate(names)},
        'total': budget,
    }
"}
